let contribChart, familyChart, histChart, scatterChart, boxChart;

function normalizeAbs(v, best, worst){
  const lo = Math.min(best,worst), hi = Math.max(best,worst);
  const c = Math.min(Math.max(v,lo),hi);
  return best < worst ? (worst-c)/(worst-best) : (c-worst)/(best-worst);
}
function contribPoints(row){
  const s_w = normalizeAbs(row.WAPE/100, 0.05, 0.40);
  const s_b = normalizeAbs(row.Bias/100, 0.00, 0.20);
  const s_s = normalizeAbs(row.Stability, 0.00, 0.30);
  const s_h = normalizeAbs(row.Hit10/100, 0.90, 0.30);
  return [35*s_w, 25*s_h, 20*s_b, 20*s_s];
}

let lbSort = {key:'CompositeScore', asc:false};
let currentLeaderboard = [];

function renderLeaderboard(filter=''){
  let rows = currentLeaderboard.slice();
  if(filter) rows = rows.filter(r=>r.Model.toLowerCase().includes(filter.toLowerCase()));
  rows.sort((a,b)=>{
    let av=a[lbSort.key], bv=b[lbSort.key];
    if(typeof av === 'string') return lbSort.asc ? av.localeCompare(bv) : bv.localeCompare(av);
    return lbSort.asc ? av-bv : bv-av;
  });
  document.querySelectorAll('#leaderboard-table th').forEach(th=>{
    th.classList.toggle('sorted', th.dataset.k===lbSort.key);
    th.classList.toggle('asc', th.dataset.k===lbSort.key && lbSort.asc);
  });
  const body = document.getElementById('lb-body');
  body.innerHTML = rows.map((r,i)=>{
    const rank = currentLeaderboard.indexOf(r)+1;
    let badgeCls = rank===1 ? 'top1' : rank===2 ? 'top2' : rank===3 ? 'top3' : '';
    const barPct = Math.max(2, Math.min(100, r.CompositeScore));
    return `<tr style="animation-delay:${Math.min(i*0.012,0.3)}s">
      <td><span class="rank-badge ${badgeCls}">${rank}</span></td>
      <td>${r.Model}</td>
      <td class="num"><div class="score-cell"><span>${r.CompositeScore.toFixed(2)}</span><div class="score-bar-track"><div class="score-bar-fill" style="width:${barPct}%"></div></div></div></td>
      <td class="num">${r.WAPE.toFixed(2)}</td>
      <td class="num">${r.Hit10.toFixed(2)}</td>
      <td class="num">${r.Bias.toFixed(2)}</td>
      <td class="num">${r.Stability.toFixed(3)}</td>
      <td class="num">${r.n_rows}</td>
    </tr>`;
  }).join('');
}
document.querySelectorAll('#leaderboard-table th').forEach(th=>{
  th.addEventListener('click', ()=>{
    const k = th.dataset.k;
    if(k==='rank') return;
    if(lbSort.key===k) lbSort.asc=!lbSort.asc; else {lbSort.key=k; lbSort.asc=false;}
    renderLeaderboard(document.getElementById('lb-search').value);
  });
});
document.getElementById('lb-search').addEventListener('input', e=>renderLeaderboard(e.target.value));

// Corrected renderQ2 using DATA.filters, graceful uppercase mapping, and dynamic navcard updates
function renderQ2(sr, fy, q){
  const srMapped = sr === 'all' ? 'All' : sr;
  const fyMapped = fy === 'all' ? 'All' : fy;
  const qMapped = q === 'all' ? 'All' : q;

  const key = `${srMapped}|${fyMapped}|${qMapped}`;
  const slice = DATA.filters.slices[key];
  if(!slice){
    document.getElementById('q2-champ').textContent = 'No qualifying models';
    document.getElementById('q2-champ-score').textContent = '—';
    document.getElementById('q2-runner').textContent = '—';
    document.getElementById('q2-conf').innerHTML = chip('Low');
    document.getElementById('lb-count-note').textContent = '(this filter combination has fewer than 30 rows for every model — insufficient data to score)';
    document.getElementById('q2-observation').textContent = 'No model met the minimum 30-row eligibility threshold for this filter combination.';
    document.getElementById('q2-conclusion').textContent = 'Insufficient data to identify a champion for this slice.';
    document.getElementById('q2-decision-support').textContent = 'Consider broadening the Sub-Region, Fiscal Year, or Quarter filter to increase the evaluated sample size.';
    document.getElementById('q2-rec-suppressed').textContent = 'Recommendation omitted: no eligible candidates in this slice.';
    currentLeaderboard = [];
    renderLeaderboard(document.getElementById('lb-search').value);
    if(contribChart){ contribChart.destroy(); contribChart = null; }
    return;
  }
  currentLeaderboard = slice.leaderboard;
  const champRow = slice.leaderboard[0];
  const runnerRow = slice.leaderboard[1] || slice.leaderboard[0];

  document.getElementById('q2-champ').textContent = champRow.Model;
  const scoreEl = document.getElementById('q2-champ-score');
  scoreEl.textContent = '';
  countUp(scoreEl, champRow.CompositeScore, {decimals:2});
  document.getElementById('q2-runner').textContent = runnerRow.Model;
  document.getElementById('lb-count-note').textContent = `(${slice.n_models} eligible models, ≥30 rows, ${slice.n_rows.toLocaleString()} total rows in slice)`;

  const conf = (srMapped==='All' && fyMapped==='All' && qMapped==='All') ? DATA.q2.confidence : 'Low';
  document.getElementById('q2-conf').innerHTML = chip(conf);
  document.getElementById('q2-observation').textContent =
    `${champRow.Model} ranked first among ${slice.n_models} eligible models with a Composite Score of ${champRow.CompositeScore.toFixed(2)}. ${runnerRow.Model} ranked second at ${runnerRow.CompositeScore.toFixed(2)}.`;
  document.getElementById('q2-conclusion').textContent = `${champRow.Model} scored highest in this slice, but per-slice statistical testing was not pre-computed for filtered views — treat as a ranking, not a proven champion.`;
  document.getElementById('q2-decision-support').textContent = `Composite score gap: ${(champRow.CompositeScore-runnerRow.CompositeScore).toFixed(2)} points. This should be considered alongside the global (unfiltered) significance test shown when no filters are applied.`;
  document.getElementById('q2-rec-suppressed').textContent = 'Recommendation omitted: confidence for filtered slices is treated conservatively as Low pending dedicated significance testing.';

  renderLeaderboard(document.getElementById('lb-search').value);

  // contribution chart
  const champPts = contribPoints(champRow), runnerPts = contribPoints(runnerRow);
  if(contribChart) contribChart.destroy();
  contribChart = new Chart(document.getElementById('chart-q2-contrib'), {
    type:'bar',
    data:{ labels:[champRow.Model, runnerRow.Model],
      datasets:[
        {label:'WAPE (35%)', data:[champPts[0], runnerPts[0]], backgroundColor:COLORS.navy},
        {label:'Hit10 (25%)', data:[champPts[1], runnerPts[1]], backgroundColor:COLORS.teal},
        {label:'Bias (20%)', data:[champPts[2], runnerPts[2]], backgroundColor:COLORS.amber},
        {label:'Stability (20%)', data:[champPts[3], runnerPts[3]], backgroundColor:COLORS.gray},
      ]},
    options:{responsive:true, maintainAspectRatio:false, indexAxis:'y',
      plugins:{legend:{position:'bottom', labels:{boxWidth:10}}},
      scales:{x:{stacked:true, max:100, grid:{color:'#EEF1F4'}}, y:{stacked:true, grid:{display:false}}}}
  });
}

// Function to update dynamic texts & KPI cards across the dashboard when filters change
function updateDynamicTexts() {
  const isGlobal = (srSelect?.value === 'all' || !srSelect) && 
                   (fySelect?.value === 'all' || !fySelect) && 
                   (chSelect?.value === 'all' || !chSelect);
                   
  const { series } = getFilteredQ1Series();
  const count = series.length;
  let manualWape = 0;
  let mlWape = 0;
  let winCount = 0;
  if (count > 0) {
    let sumManual = 0;
    let sumMl = 0;
    series.forEach(d => {
      sumManual += d.manual_wape;
      sumMl += d.ml_wape;
      if (d.manual_wape < d.ml_wape) {
        winCount++;
      }
    });
    manualWape = sumManual / count;
    mlWape = sumMl / count;
  }
  const winRate = count > 0 ? (winCount / count * 100) : 0;
  const absImprovement = mlWape - manualWape;

  const q1ManualWapeVal = isGlobal ? DATA.q1.manual_wape : parseFloat(manualWape.toFixed(2));
  const q1MlWapeVal = isGlobal ? DATA.q1.ml_wape : parseFloat(mlWape.toFixed(2));
  const q1AbsImprovementVal = isGlobal ? DATA.q1.abs_improvement : parseFloat(absImprovement.toFixed(2));
  const q1WinRateVal = isGlobal ? DATA.q1.manual_win_rate : parseFloat(winRate.toFixed(1));
  const q1PValText = isGlobal ? DATA.q1.p_value.toExponential(3) : 'N/A';
  const q1EffectSizeText = isGlobal ? DATA.q1.effect_size.toString() : 'N/A';
  const q1SampleSizeText = `${count} weeks`;
  const q1ConfidenceText = isGlobal ? DATA.q1.confidence : (q1ManualWapeVal < q1MlWapeVal && q1WinRateVal > 60 ? 'High' : 'Low');

  // Q2 values
  const srMapped = srSelect ? (srSelect.value === 'all' ? 'All' : srSelect.value) : 'All';
  const fyMapped = fySelect ? (fySelect.value === 'all' ? 'All' : fySelect.value) : 'All';
  const key = `${srMapped}|${fyMapped}|All`;
  const slice = DATA.filters.slices[key];
  
  const q2Champ = slice ? slice.leaderboard[0].Model : 'No qualifying models';
  const q2ChampScore = slice ? slice.leaderboard[0].CompositeScore : 0;
  const q2Conf = slice ? ((srMapped === 'All' && fyMapped === 'All') ? DATA.q2.confidence : 'Low') : 'Low';

  // 1. #exec-summary-text
  const execSummaryTextEl = document.getElementById('exec-summary-text');
  if (execSummaryTextEl) {
    const q1PerformancePhrase = q1ManualWapeVal < q1MlWapeVal 
      ? `Manual forecasting outperformed the aggregate ML system with ${q1ConfidenceText.toLowerCase()} confidence (Q1)`
      : `The aggregate ML system outperformed manual forecasting (Q1)`;
      
    const q2Phrase = slice 
      ? `the top-ranked model by composite score is <b>${q2Champ}</b> (${q2ChampScore.toFixed(2)}/100), though its lead over the runner-up did not clear the policy's confidence threshold (Q2)`
      : `no model met the eligibility criteria to be graded in this slice (Q2)`;

    execSummaryTextEl.innerHTML = 
      `<b>Operational Decision: ${isGlobal ? DATA.executive.decision : (q1ManualWapeVal < q1MlWapeVal ? 'Retain Manual Forecast' : 'Evaluate ML Deployment')}.</b> ` +
      `Across all four evaluated business questions: ` +
      `${q1PerformancePhrase}; ` +
      `${q2Phrase}; ` +
      `underlying demand volume was stable, with a coefficient of variation of ${DATA.q3.cv}%, well below the 15% high-volatility trigger (Q3); ` +
      `and forecast error was only marginally higher during the ${DATA.q4.n_anomalies} detected demand anomalies, with low confidence in that association given the small sample (Q4). ` +
      `No deployment change is currently justified by the evidence.`;
  }

  // 2. #navcard-q1-headline & #navcard-q1-chip
  const navcardQ1HeadlineEl = document.getElementById('navcard-q1-headline');
  if (navcardQ1HeadlineEl) navcardQ1HeadlineEl.textContent = `${q1ManualWapeVal}% vs ${q1MlWapeVal}%`;
  const navcardQ1ChipEl = document.getElementById('navcard-q1-chip');
  if (navcardQ1ChipEl) navcardQ1ChipEl.innerHTML = chip(q1ConfidenceText);

  // 3. #navcard-q2-headline & #navcard-q2-chip
  const navcardQ2HeadlineEl = document.getElementById('navcard-q2-headline');
  if (navcardQ2HeadlineEl) navcardQ2HeadlineEl.textContent = q2Champ;
  const navcardQ2ChipEl = document.getElementById('navcard-q2-chip');
  if (navcardQ2ChipEl) {
    navcardQ2ChipEl.innerHTML = chip(q2Conf) + (slice ? ` <span style="font-size:11px;color:var(--text-2);">score ${q2ChampScore.toFixed(2)}</span>` : '');
  }

  // 4. #exec-observation
  const execObservationEl = document.getElementById('exec-observation');
  if (execObservationEl) {
    execObservationEl.textContent = `Manual WAPE was ${q1ManualWapeVal}%. ML WAPE was ${q1MlWapeVal}%. Manual outperformed ML in ${q1WinRateVal}% of ${q1SampleSizeText}.`;
  }
  
  // 5. #exec-ev-* KPI cards
  const execEvManualEl = document.getElementById('exec-ev-manual');
  if (execEvManualEl) execEvManualEl.textContent = `${q1ManualWapeVal}%`;
  const execEvMlEl = document.getElementById('exec-ev-ml');
  if (execEvMlEl) execEvMlEl.textContent = `${q1MlWapeVal}%`;
  const execEvWinrateEl = document.getElementById('exec-ev-winrate');
  if (execEvWinrateEl) execEvWinrateEl.textContent = `${q1WinRateVal}%`;
  const execEvPEl = document.getElementById('exec-ev-p');
  if (execEvPEl) execEvPEl.textContent = q1PValText;

  // 6. #q1-observation
  const q1ObservationEl = document.getElementById('q1-observation');
  if (q1ObservationEl) {
    q1ObservationEl.textContent = `Manual WAPE was ${q1ManualWapeVal}%. ML WAPE was ${q1MlWapeVal}%. Manual outperformed ML in ${q1WinRateVal}% of evaluated weeks.`;
  }

  // 7. #q1-primary
  const q1PrimaryEl = document.getElementById('q1-primary');
  if (q1PrimaryEl) {
    q1PrimaryEl.innerHTML = `
      <tr><td>Manual WAPE</td><td>${q1ManualWapeVal}%</td></tr>
      <tr><td>ML WAPE</td><td>${q1MlWapeVal}%</td></tr>
      <tr><td>Absolute Improvement (ML vs Manual)</td><td>${q1AbsImprovementVal > 0 ? '+' : ''}${q1AbsImprovementVal}pp</td></tr>`;
  }

  // 8. #q1-supporting
  const q1SupportingEl = document.getElementById('q1-supporting');
  if (q1SupportingEl) {
    q1SupportingEl.innerHTML = `
      <tr><td>Weekly Win Rate (Manual)</td><td>${q1WinRateVal}%</td></tr>
      <tr><td>Statistical Significance (Wilcoxon, p)</td><td>${q1PValText}</td></tr>
      <tr><td>Effect Size</td><td>${q1EffectSizeText}</td></tr>
      <tr><td>Sample Size</td><td>${q1SampleSizeText}</td></tr>`;
  }

  const execConclusionEl = document.getElementById('exec-conclusion');
  if (execConclusionEl) {
    execConclusionEl.textContent = q1ManualWapeVal < q1MlWapeVal
      ? `Manual forecasts were more accurate than the aggregate ML system across ${q1SampleSizeText}, with ${q1ConfidenceText.toLowerCase()} statistical confidence.`
      : `The aggregate ML system was more accurate than manual forecasts across ${q1SampleSizeText}, with ${q1ConfidenceText.toLowerCase()} statistical confidence.`;
  }
  const execRecEl = document.getElementById('exec-rec');
  if (execRecEl) {
    execRecEl.textContent = q1ManualWapeVal < q1MlWapeVal
      ? `Recommendation: Retain the Manual Forecast as the primary production forecasting method.`
      : `Recommendation: Consider evaluating the ML system for production deployment in this slice.`;
  }
  const q1ConclusionEl = document.getElementById('q1-conclusion');
  if (q1ConclusionEl) {
    q1ConclusionEl.textContent = q1ManualWapeVal < q1MlWapeVal
      ? `Manual forecasts were more accurate than the aggregate ML system across ${q1SampleSizeText}, with ${q1ConfidenceText.toLowerCase()} statistical confidence.`
      : `The aggregate ML system was more accurate than manual forecasts across ${q1SampleSizeText}, with ${q1ConfidenceText.toLowerCase()} statistical confidence.`;
  }
  const q1RecEl = document.getElementById('q1-rec');
  if (q1RecEl) {
    q1RecEl.innerHTML = chip(q1ConfidenceText) + ' &nbsp;' + (q1ManualWapeVal < q1MlWapeVal
      ? `Retain the Manual Forecast as the primary production forecasting method.`
      : `Consider evaluating the ML system for production deployment in this slice.`);
  }
}

